package com.spai.portal.task.repository;import com.spai.portal.task.domain.DeliveryTask;import java.util.*;import org.springframework.data.jpa.repository.*;import org.springframework.data.repository.query.Param;public interface DeliveryTaskRepository extends JpaRepository<DeliveryTask,String>{@Query("select t from DeliveryTask t where t.enabled=true and (:stage is null or t.stage=:stage) and (:scene is null or t.scene=:scene) and (:output is null or t.output=:output) and (:skill is null or t.skill=:skill) and (:priority is null or t.priority=:priority) and (:difficulty is null or t.difficulty=:difficulty) and (:type is null or t.type=:type) order by t.externalId")List<DeliveryTask>filter(@Param("stage")String stage,@Param("scene")String scene,@Param("output")String output,@Param("skill")String skill,@Param("priority")String priority,@Param("difficulty")String difficulty,@Param("type")String type);Optional<DeliveryTask>findByExternalId(String externalId);}
